-- mmbookhouse — RESET public schema + all migrations (DESTRUCTIVE)
-- Generated by scripts/db-bundle.mjs — edit the files in supabase/migrations instead.

-- ============================================================================
-- mmbookhouse — RESET PUBLIC SCHEMA  (DESTRUCTIVE, run once, by the owner)
-- ----------------------------------------------------------------------------
-- Deletes EVERY table, view, function, type and row in the `public` schema and
-- recreates it empty with the standard Supabase grants. It does NOT touch
-- `auth` (customer/staff accounts stay), `storage` or other schemas.
--
-- Run this in: Supabase Dashboard -> SQL Editor. Then run the migrations in
-- supabase/migrations/ (or the single file supabase/all_migrations.sql).
--
-- If you still need the old data, run the encrypted backup first
-- (GitHub Actions -> "Encrypted database backup" -> Run workflow).
-- ============================================================================

drop schema if exists public cascade;
create schema public;

alter schema public owner to postgres;

grant usage on schema public to postgres, anon, authenticated, service_role;
grant all on schema public to postgres, service_role;

-- Same defaults a fresh Supabase project has; RLS (enabled per table in the
-- migrations) is what actually protects the data.
alter default privileges in schema public grant all on tables    to postgres, service_role;
alter default privileges in schema public grant all on functions to postgres, service_role;
alter default privileges in schema public grant all on sequences to postgres, service_role;

alter default privileges in schema public grant select, insert, update, delete on tables to anon, authenticated;
alter default privileges in schema public grant execute on functions to anon, authenticated;
alter default privileges in schema public grant usage, select on sequences to anon, authenticated;

comment on schema public is 'mmbookhouse storefront + admin (rebuild v2)';

-- ===== 0001_foundation.sql =====
-- 0001 Foundation: extensions, helpers, profiles, staff, settings, audit, rate limits, backups
-- Idempotent where practical; designed to run on a freshly reset `public` schema.

create schema if not exists extensions;
create extension if not exists pg_trgm with schema extensions;
-- Search functions run as the caller, so the roles need to see the trigram functions.
grant usage on schema extensions to anon, authenticated, service_role;

-- ---------------------------------------------------------------- helpers ---
create or replace function public.set_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

-- Recognises the logged-in user in Supabase (auth.uid()) and in the PGlite test harness.
-- Server-only functions (service_role) must revoke execute from anon/authenticated.

-- ---------------------------------------------------------------- profiles ---
create table public.profiles (
  id          uuid primary key references auth.users(id) on delete cascade,
  full_name   text,
  phone       text check (phone is null or phone ~ '^[0-9+][0-9 -]{7,14}$'),
  avatar_url  text,
  lang        text not null default 'bn' check (lang in ('bn', 'en')),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create trigger trg_profiles_updated before update on public.profiles
  for each row execute function public.set_updated_at();

alter table public.profiles enable row level security;
create policy profiles_select_own on public.profiles for select to authenticated
  using (id = auth.uid());
create policy profiles_update_own on public.profiles for update to authenticated
  using (id = auth.uid()) with check (id = auth.uid());

-- Every new auth user gets a profile row.
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, full_name, phone, avatar_url)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'),
    null,
    new.raw_user_meta_data ->> 'avatar_url'
  )
  on conflict (id) do nothing;
  return new;
end $$;
revoke execute on function public.handle_new_user() from public, anon, authenticated;

create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- ------------------------------------------------------------------- staff ---
create type public.staff_role as enum ('super_admin', 'inventory_manager', 'dispatch_staff');

create table public.staff_members (
  user_id       uuid primary key references auth.users(id) on delete cascade,
  role          public.staff_role not null,
  display_name  text,
  is_active     boolean not null default true,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create trigger trg_staff_updated before update on public.staff_members
  for each row execute function public.set_updated_at();

alter table public.staff_members enable row level security;
-- A staff member may read only their own row; everything else is service-role only.
create policy staff_select_own on public.staff_members for select to authenticated
  using (user_id = auth.uid());

