-- ----------------------------------------------------------------- audit ---
create table public.audit_logs (
  id          bigint generated always as identity primary key,
  actor_id    uuid references auth.users(id) on delete set null,
  actor_role  text,
  action      text not null,
  entity      text not null,
  entity_id   text,
  before_data jsonb,
  after_data  jsonb,
  ip          text,
  created_at  timestamptz not null default now()
);
create index idx_audit_created on public.audit_logs (created_at desc);
create index idx_audit_entity on public.audit_logs (entity, entity_id);
alter table public.audit_logs enable row level security;   -- service role only

-- Append-only: nobody (not even service role) can edit history through the API.
-- The single allowed change is the FK action "on delete set null" for actor_id.
create or replace function public.audit_logs_immutable() returns trigger
language plpgsql as $$
begin
  if tg_op = 'UPDATE'
     and new.actor_id is null
     and (to_jsonb(new) - 'actor_id') = (to_jsonb(old) - 'actor_id') then
    return new;
  end if;
  raise exception 'audit_logs is append-only';
end $$;
create trigger trg_audit_no_update before update or delete on public.audit_logs
  for each row execute function public.audit_logs_immutable();

-- ----------------------------------------------------------- rate limits ---
create table public.rate_limits (
  key           text primary key,
  window_start  timestamptz not null default now(),
  hits          integer not null default 0,
  blocked_until timestamptz
);
alter table public.rate_limits enable row level security;   -- service role only

-- Fixed-window limiter. Returns true when the call is allowed.
-- Exceeding `p_max` inside the window blocks the key for `p_block_seconds`.
create or replace function public.hit_rate_limit(
  p_key text, p_max integer, p_window_seconds integer, p_block_seconds integer default 0
) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  r public.rate_limits;
begin
  insert into public.rate_limits (key, window_start, hits)
  values (p_key, now(), 0)
  on conflict (key) do nothing;

  select * into r from public.rate_limits where key = p_key for update;

  if r.blocked_until is not null and r.blocked_until > now() then
    return false;
  end if;

  if r.window_start < now() - make_interval(secs => p_window_seconds) then
    update public.rate_limits set window_start = now(), hits = 1, blocked_until = null where key = p_key;
    return true;
  end if;

  if r.hits + 1 > p_max then
    update public.rate_limits
       set hits = r.hits + 1,
           blocked_until = case when p_block_seconds > 0 then now() + make_interval(secs => p_block_seconds) else null end
     where key = p_key;
    return false;
  end if;

  update public.rate_limits set hits = r.hits + 1 where key = p_key;
  return true;
end $$;

create or replace function public.reset_rate_limit(p_key text) returns void
language sql security definer set search_path = public as $$
  delete from public.rate_limits where key = p_key;
$$;

revoke execute on function public.hit_rate_limit(text, integer, integer, integer) from public, anon, authenticated;
revoke execute on function public.reset_rate_limit(text) from public, anon, authenticated;

-- ---------------------------------------------------------- backup jobs ---
-- Used by the GitHub Actions backup workflow and the admin "Backups" page.
create table public.backup_jobs (
  id                    uuid primary key default gen_random_uuid(),
  trigger_type          text not null check (trigger_type in ('manual', 'scheduled')),
  status                text not null default 'queued'
                          check (status in ('queued', 'running', 'succeeded', 'failed')),
  requested_by          uuid references auth.users(id) on delete set null,
  file_name             text,
  drive_file_id         text,
  drive_web_view_link   text,
  file_size_bytes       bigint check (file_size_bytes is null or file_size_bytes >= 0),
  sha256                text,
  error_message         text,
  started_at            timestamptz,
  completed_at          timestamptz,
  created_at            timestamptz not null default now()
);
create index idx_backup_jobs_created on public.backup_jobs (created_at desc);
alter table public.backup_jobs enable row level security;   -- service role only


-- ===== 0002_catalog.sql =====
-- 0002 Catalog: publishers, authors, categories, books, inventory, flash deals, public view

-- ------------------------------------------------------------- publishers ---
create table public.publishers (
  id       uuid primary key default gen_random_uuid(),
  slug     text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]*$'),
  name     text not null,
  name_bn  text,
  created_at timestamptz not null default now()
);
create table public.authors (
  id       uuid primary key default gen_random_uuid(),
  slug     text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]*$'),
  name     text not null,
  name_bn  text,
  bio      text,
  created_at timestamptz not null default now()
);
create index idx_authors_name_trgm on public.authors using gin (name extensions.gin_trgm_ops);
create index idx_authors_name_bn_trgm on public.authors using gin (name_bn extensions.gin_trgm_ops);

-- ------------------------------------------------------------- categories ---
create table public.categories (
  id          uuid primary key default gen_random_uuid(),
  parent_id   uuid references public.categories(id) on delete restrict,
  slug        text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]*$'),
  name        text not null,
  name_bn     text,
  image_url   text,
  sort_order  integer not null default 0,
  is_active   boolean not null default true,
  show_on_home boolean not null default false,
  created_at  timestamptz not null default now(),
  check (parent_id is distinct from id)
);
create index idx_categories_parent on public.categories (parent_id, sort_order);

-- ------------------------------------------------------------------ books ---
create type public.book_status as enum ('draft', 'active', 'archived');

create table public.books (
  id             uuid primary key default gen_random_uuid(),
  slug           text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]*$'),
  title          text not null check (length(btrim(title)) > 0),
  title_bn       text,
  subtitle       text,
  description    text,
  description_bn text,
  isbn           text unique check (isbn is null or isbn ~ '^[0-9]{10}([0-9]{3})?$'),
  publisher_id   uuid references public.publishers(id) on delete set null,
  language       text not null default 'bn' check (language in ('bn', 'en', 'hi', 'ur', 'sa', 'other')),
  edition        text,
  edition_year   integer check (edition_year is null or edition_year between 1800 and 2100),
  pages          integer check (pages is null or pages > 0),
  binding        text not null default 'paperback' check (binding in ('paperback', 'hardcover')),
  condition      text not null default 'new' check (condition in ('new', 'used')),
  weight_g       integer check (weight_g is null or weight_g > 0),
  class_level    text,
  mrp            numeric(10, 2) not null check (mrp >= 0),
  sale_price     numeric(10, 2) not null check (sale_price >= 0),
  hsn_code       text not null default '4901',
  gst_rate       numeric(5, 2) not null default 0 check (gst_rate between 0 and 28),
  cover_url      text,
  gallery        jsonb not null default '[]'::jsonb,
  preview_pages  jsonb not null default '[]'::jsonb,
  status         public.book_status not null default 'draft',
  is_featured    boolean not null default false,
  sold_count     integer not null default 0 check (sold_count >= 0),
  rating_avg     numeric(3, 2) not null default 0,
  rating_count   integer not null default 0,
  search_text    text not null default '',
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  check (sale_price <= mrp)
);
create index idx_books_status on public.books (status);
create index idx_books_publisher on public.books (publisher_id);
create index idx_books_created on public.books (created_at desc) where status = 'active';
create index idx_books_sold on public.books (sold_count desc) where status = 'active';
create index idx_books_search_trgm on public.books using gin (search_text extensions.gin_trgm_ops);
create trigger trg_books_updated before update on public.books
  for each row execute function public.set_updated_at();

create table public.book_authors (
  book_id    uuid not null references public.books(id) on delete cascade,
  author_id  uuid not null references public.authors(id) on delete cascade,
  role       text not null default 'author' check (role in ('author', 'editor', 'translator')),
  position   integer not null default 0,
  primary key (book_id, author_id, role)
);
create index idx_book_authors_author on public.book_authors (author_id);

create table public.book_categories (
  book_id      uuid not null references public.books(id) on delete cascade,
  category_id  uuid not null references public.categories(id) on delete cascade,
  primary key (book_id, category_id)
);
create index idx_book_categories_cat on public.book_categories (category_id);

-- Staff-only data (wholesale cost, shelf location). Never exposed to customers.
create table public.book_private (
  book_id        uuid primary key references public.books(id) on delete cascade,
  cost_price     numeric(10, 2) check (cost_price is null or cost_price >= 0),
  rack_location  text,
  supplier_note  text
);

-- Frequently bought together / related titles curated by the owner.
create table public.related_books (
  book_id          uuid not null references public.books(id) on delete cascade,
  related_book_id  uuid not null references public.books(id) on delete cascade,
  kind             text not null default 'fbt' check (kind in ('fbt', 'similar')),
  position         integer not null default 0,
  primary key (book_id, related_book_id, kind),
  check (book_id <> related_book_id)
);

-- -------------------------------------------------------------- inventory ---
create table public.inventory (
  book_id              uuid primary key references public.books(id) on delete cascade,
  on_hand              integer not null default 0 check (on_hand >= 0),
  low_stock_threshold  integer not null default 5 check (low_stock_threshold >= 0),
  updated_at           timestamptz not null default now()
);
create trigger trg_inventory_updated before update on public.inventory
  for each row execute function public.set_updated_at();

create table public.stock_movements (
  id          bigint generated always as identity primary key,
  book_id     uuid not null references public.books(id) on delete cascade,
  delta       integer not null check (delta <> 0),
  reason      text not null check (reason in ('order', 'cancel', 'return', 'restock', 'adjust', 'pos_sale', 'import')),
  order_id    uuid,
  note        text,
  actor_id    uuid references auth.users(id) on delete set null,
  created_at  timestamptz not null default now()
);
create index idx_stock_movements_book on public.stock_movements (book_id, created_at desc);
alter table public.stock_movements enable row level security;   -- service role only

create or replace function public.books_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.inventory (book_id) values (new.id) on conflict do nothing;
  insert into public.book_private (book_id) values (new.id) on conflict do nothing;
  return new;
end $$;
revoke execute on function public.books_after_insert() from public, anon, authenticated;
create trigger trg_books_after_insert after insert on public.books
  for each row execute function public.books_after_insert();

-- ------------------------------------------------------- search text sync ---
-- One lowercase blob (titles, authors, publisher, ISBN) that trigram search runs on.
create or replace function public.refresh_book_search(p_book uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  update public.books b
     set search_text = lower(concat_ws(' ',
           b.title, b.title_bn, b.subtitle, b.isbn,
           (select string_agg(concat_ws(' ', a.name, a.name_bn), ' ')
              from public.book_authors ba join public.authors a on a.id = ba.author_id
             where ba.book_id = b.id),
           (select concat_ws(' ', p.name, p.name_bn) from public.publishers p where p.id = b.publisher_id)))
   where b.id = p_book;
end $$;
revoke execute on function public.refresh_book_search(uuid) from public, anon, authenticated;

create or replace function public.trg_books_search() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  new.search_text := lower(concat_ws(' ',
    new.title, new.title_bn, new.subtitle, new.isbn,
    (select string_agg(concat_ws(' ', a.name, a.name_bn), ' ')
       from public.book_authors ba join public.authors a on a.id = ba.author_id
      where ba.book_id = new.id),
    (select concat_ws(' ', p.name, p.name_bn) from public.publishers p where p.id = new.publisher_id)));
  return new;
end $$;
revoke execute on function public.trg_books_search() from public, anon, authenticated;
create trigger trg_books_search before insert or update of title, title_bn, subtitle, isbn, publisher_id
  on public.books for each row execute function public.trg_books_search();

create or replace function public.trg_book_authors_search() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  perform public.refresh_book_search(coalesce(new.book_id, old.book_id));
  return null;
end $$;
revoke execute on function public.trg_book_authors_search() from public, anon, authenticated;
create trigger trg_book_authors_search after insert or update or delete on public.book_authors
  for each row execute function public.trg_book_authors_search();

-- ------------------------------------------------------------ flash deals ---
create table public.flash_deals (
  id          uuid primary key default gen_random_uuid(),
  book_id     uuid not null references public.books(id) on delete cascade,
  deal_price  numeric(10, 2) not null check (deal_price >= 0),
  title       text,
  starts_at   timestamptz not null default now(),
  ends_at     timestamptz not null,
  is_active   boolean not null default true,
  created_at  timestamptz not null default now(),
  check (ends_at > starts_at)
);
create index idx_flash_deals_book on public.flash_deals (book_id);
create index idx_flash_deals_window on public.flash_deals (starts_at, ends_at) where is_active;

-- Price a customer pays right now: the cheapest live deal, never above sale_price.
create or replace function public.book_effective_price(p_book uuid) returns numeric
language sql stable set search_path = public as $$
  select least(
    b.sale_price,
    coalesce((select min(d.deal_price) from public.flash_deals d
               where d.book_id = b.id and d.is_active
                 and now() >= d.starts_at and now() < d.ends_at), b.sale_price))
  from public.books b where b.id = p_book;
$$;

-- ------------------------------------------------------------ public view ---
create view public.v_books with (security_invoker = true) as
select
  b.id, b.slug, b.title, b.title_bn, b.subtitle, b.cover_url, b.language, b.binding,
  b.condition, b.is_featured, b.sold_count, b.rating_avg, b.rating_count, b.created_at,
  b.publisher_id, p.name as publisher_name, p.name_bn as publisher_name_bn,
  b.mrp, b.sale_price,
  eff.price as price,
  case when b.mrp > 0 then round((b.mrp - eff.price) * 100 / b.mrp)::int else 0 end as discount_pct,
  eff.deal_ends_at,
  coalesce(i.on_hand, 0) as on_hand,
  coalesce(i.on_hand, 0) > 0 as in_stock,
  coalesce(i.on_hand, 0) <= coalesce(i.low_stock_threshold, 5) as low_stock,
  (select string_agg(a.name, ', ' order by ba.position)
     from public.book_authors ba join public.authors a on a.id = ba.author_id
    where ba.book_id = b.id and ba.role = 'author') as author_names,
  (select string_agg(coalesce(a.name_bn, a.name), ', ' order by ba.position)
     from public.book_authors ba join public.authors a on a.id = ba.author_id
    where ba.book_id = b.id and ba.role = 'author') as author_names_bn
from public.books b
left join public.publishers p on p.id = b.publisher_id
left join public.inventory i on i.book_id = b.id
cross join lateral (
  select least(b.sale_price, coalesce(
           (select min(d.deal_price) from public.flash_deals d
             where d.book_id = b.id and d.is_active and now() >= d.starts_at and now() < d.ends_at),
           b.sale_price)) as price,
         (select min(d.ends_at) from public.flash_deals d
           where d.book_id = b.id and d.is_active and now() >= d.starts_at and now() < d.ends_at
             and d.deal_price < b.sale_price) as deal_ends_at
) eff;

-- -------------------------------------------------------------------- RLS ---
alter table public.publishers      enable row level security;
alter table public.authors         enable row level security;
alter table public.categories      enable row level security;
alter table public.books           enable row level security;
alter table public.book_authors    enable row level security;
alter table public.book_categories enable row level security;
alter table public.book_private    enable row level security;   -- service role only
alter table public.related_books   enable row level security;
alter table public.inventory       enable row level security;
alter table public.flash_deals     enable row level security;

create policy publishers_read on public.publishers for select to anon, authenticated using (true);
create policy authors_read on public.authors for select to anon, authenticated using (true);
create policy categories_read on public.categories for select to anon, authenticated using (is_active);
create policy books_read on public.books for select to anon, authenticated using (status = 'active');
create policy book_authors_read on public.book_authors for select to anon, authenticated
  using (exists (select 1 from public.books b where b.id = book_id and b.status = 'active'));
create policy book_categories_read on public.book_categories for select to anon, authenticated
  using (exists (select 1 from public.books b where b.id = book_id and b.status = 'active'));
create policy related_books_read on public.related_books for select to anon, authenticated
  using (exists (select 1 from public.books b where b.id = related_books.related_book_id and b.status = 'active'));
create policy inventory_read on public.inventory for select to anon, authenticated
  using (exists (select 1 from public.books b where b.id = book_id and b.status = 'active'));
create policy flash_deals_read on public.flash_deals for select to anon, authenticated
  using (is_active and now() < ends_at);


-- ===== 0003_commerce.sql =====
-- 0003 Commerce: cart, wishlist, addresses, delivery, coupons, orders, payments, RPCs
-- All money is INR with 2 decimals. Prices are always recomputed on the server.

-- ---------------------------------------------------------------- cart ---
create table public.cart_items (
  user_id         uuid not null references auth.users(id) on delete cascade,
  book_id         uuid not null references public.books(id) on delete cascade,
  qty             integer not null default 1 check (qty between 1 and 99),
  saved_for_later boolean not null default false,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  primary key (user_id, book_id)
);
create trigger trg_cart_updated before update on public.cart_items
  for each row execute function public.set_updated_at();

create table public.wishlist_items (
  user_id     uuid not null references auth.users(id) on delete cascade,
  book_id     uuid not null references public.books(id) on delete cascade,
  created_at  timestamptz not null default now(),
  primary key (user_id, book_id)
);

create table public.stock_alerts (
  user_id     uuid not null references auth.users(id) on delete cascade,
  book_id     uuid not null references public.books(id) on delete cascade,
  created_at  timestamptz not null default now(),
  notified_at timestamptz,
  primary key (user_id, book_id)
);

alter table public.cart_items     enable row level security;
alter table public.wishlist_items enable row level security;
alter table public.stock_alerts   enable row level security;
create policy cart_own on public.cart_items for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy wishlist_own on public.wishlist_items for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy stock_alerts_own on public.stock_alerts for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

-- ------------------------------------------------------------ addresses ---
create table public.addresses (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users(id) on delete cascade,
  label       text not null default 'Home',
  full_name   text not null check (length(btrim(full_name)) > 1),
  phone       text not null check (phone ~ '^[0-9+][0-9 -]{7,14}$'),
  line1       text not null check (length(btrim(line1)) > 2),
  line2       text,
  landmark    text,
  city        text not null,
  district    text,
  state       text not null default 'West Bengal',
  pincode     text not null check (pincode ~ '^[1-9][0-9]{5}$'),
  is_default  boolean not null default false,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index idx_addresses_user on public.addresses (user_id);
create unique index uq_addresses_one_default on public.addresses (user_id) where is_default;
create trigger trg_addresses_updated before update on public.addresses
  for each row execute function public.set_updated_at();

alter table public.addresses enable row level security;
create policy addresses_own on public.addresses for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

-- Making an address default clears the previous default atomically.
create or replace function public.addresses_single_default() returns trigger
language plpgsql as $$
begin
  if new.is_default then
    update public.addresses set is_default = false
     where user_id = new.user_id and id <> new.id and is_default;
  end if;
  return new;
end $$;
create trigger trg_addresses_default before insert or update of is_default on public.addresses
  for each row when (new.is_default) execute function public.addresses_single_default();

-- ------------------------------------------------------------- delivery ---
-- match_value: '' = everywhere, otherwise a pincode prefix ('732' = the shop's own district, '732101' = one pincode).
-- The longest matching prefix wins.
create table public.delivery_rules (
  id             uuid primary key default gen_random_uuid(),
  label          text not null,
  label_bn       text,
  match_value    text not null default '' check (match_value ~ '^[0-9]{0,6}$'),
  fee            numeric(8, 2) not null default 0 check (fee >= 0),
  free_above     numeric(10, 2) check (free_above is null or free_above >= 0),
  eta_min_days   integer not null default 2 check (eta_min_days >= 0),
  eta_max_days   integer not null default 4 check (eta_max_days >= eta_min_days),
  cod_available  boolean not null default true,
  is_active      boolean not null default true,
  unique (match_value)
);
alter table public.delivery_rules enable row level security;
create policy delivery_rules_read on public.delivery_rules for select to anon, authenticated
  using (is_active);

insert into public.delivery_rules (label, label_bn, match_value, fee, free_above, eta_min_days, eta_max_days, cod_available) values
  ('Local area',         'স্থানীয় এলাকা (দোকানের কাছাকাছি)', '732', 30, 299, 1, 2, true),
  ('West Bengal',        'পশ্চিমবঙ্গ',           '7',   60, 499, 2, 4, true),
  ('Rest of India',      'ভারতের অন্যান্য অংশ',    '',    90, 799, 4, 8, false);

create or replace function public.quote_delivery(p_pincode text, p_subtotal numeric)
returns table (rule_id uuid, label text, label_bn text, fee numeric, eta_min_days int, eta_max_days int, cod_available boolean)
language sql stable set search_path = public as $$
  select r.id, r.label, r.label_bn,
         case when r.free_above is not null and p_subtotal >= r.free_above then 0::numeric else r.fee end,
         r.eta_min_days, r.eta_max_days, r.cod_available
    from public.delivery_rules r
   where r.is_active and p_pincode like r.match_value || '%'
   order by length(r.match_value) desc
   limit 1;
$$;

-- --------------------------------------------------------------- coupons ---
create table public.coupons (
  id              uuid primary key default gen_random_uuid(),
  code            text not null unique check (code = upper(code) and code ~ '^[A-Z0-9_-]{3,24}$'),
  description     text,
  kind            text not null check (kind in ('percent', 'flat')),
  value           numeric(10, 2) not null check (value > 0),
  max_discount    numeric(10, 2) check (max_discount is null or max_discount > 0),
  min_order       numeric(10, 2) not null default 0 check (min_order >= 0),
  starts_at       timestamptz,
  ends_at         timestamptz,
  usage_limit     integer check (usage_limit is null or usage_limit > 0),
  per_user_limit  integer not null default 1 check (per_user_limit > 0),
  used_count      integer not null default 0 check (used_count >= 0),
  is_active       boolean not null default true,
  created_at      timestamptz not null default now(),
  check (kind <> 'percent' or value <= 100)
);
alter table public.coupons enable row level security;   -- service role + RPC only

create table public.coupon_redemptions (
  id          uuid primary key default gen_random_uuid(),
  coupon_id   uuid not null references public.coupons(id) on delete cascade,
  user_id     uuid not null references auth.users(id) on delete cascade,
  order_id    uuid,
  amount      numeric(10, 2) not null,
  created_at  timestamptz not null default now()
);
create index idx_coupon_redemptions on public.coupon_redemptions (coupon_id, user_id);
alter table public.coupon_redemptions enable row level security;   -- service role + RPC only

create or replace function public.evaluate_coupon(p_code text, p_user uuid, p_subtotal numeric)
returns table (coupon_id uuid, discount numeric)
language plpgsql security definer set search_path = public as $$
declare
  c public.coupons;
  d numeric;
begin
  select * into c from public.coupons where code = upper(btrim(p_code)) for update;
  if not found or not c.is_active then raise exception 'COUPON_INVALID'; end if;
  if c.starts_at is not null and now() < c.starts_at then raise exception 'COUPON_NOT_STARTED'; end if;
  if c.ends_at is not null and now() > c.ends_at then raise exception 'COUPON_EXPIRED'; end if;
  if p_subtotal < c.min_order then
    raise exception 'COUPON_MIN_ORDER' using detail = c.min_order::text;
  end if;
  if c.usage_limit is not null and c.used_count >= c.usage_limit then raise exception 'COUPON_EXHAUSTED'; end if;
  if (select count(*) from public.coupon_redemptions r where r.coupon_id = c.id and r.user_id = p_user) >= c.per_user_limit then
    raise exception 'COUPON_ALREADY_USED';
  end if;

  d := case c.kind when 'percent' then floor(p_subtotal * c.value / 100) else c.value end;
  if c.max_discount is not null then d := least(d, c.max_discount); end if;
  d := least(d, p_subtotal);
  return query select c.id, d;
end $$;
revoke execute on function public.evaluate_coupon(text, uuid, numeric) from public, anon, authenticated;

-- Cart preview: does not consume the coupon.
create or replace function public.validate_coupon(p_code text, p_subtotal numeric)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  r record;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  select * into r from public.evaluate_coupon(p_code, auth.uid(), p_subtotal);
  return jsonb_build_object('code', upper(btrim(p_code)), 'discount', r.discount);
end $$;
revoke execute on function public.validate_coupon(text, numeric) from public, anon;
grant execute on function public.validate_coupon(text, numeric) to authenticated;

-- ---------------------------------------------------------------- orders ---
create sequence public.order_no_seq start 1001;

create table public.orders (
  id               uuid primary key default gen_random_uuid(),
  order_no         text not null unique,
  user_id          uuid references auth.users(id) on delete set null,
  status           text not null default 'pending' check (status in
                     ('pending', 'confirmed', 'processing', 'ready', 'dispatched', 'delivered', 'cancelled', 'returned')),
  channel          text not null default 'online' check (channel in ('online', 'pos')),
  payment_method   text not null check (payment_method in ('cod', 'upi', 'online', 'cash')),
  payment_status   text not null default 'unpaid' check (payment_status in
                     ('unpaid', 'pending_verification', 'paid', 'failed', 'refunded')),
  fulfillment      text not null default 'delivery' check (fulfillment in ('delivery', 'pickup')),
  subtotal         numeric(10, 2) not null check (subtotal >= 0),
  discount_total   numeric(10, 2) not null default 0 check (discount_total >= 0),
  delivery_fee     numeric(10, 2) not null default 0 check (delivery_fee >= 0),
  total            numeric(10, 2) not null check (total >= 0),
  coupon_code      text,
  customer_email   text,
  ship_name        text not null,
  ship_phone       text not null,
  ship_line1       text,
  ship_line2       text,
  ship_landmark    text,
  ship_city        text,
  ship_district    text,
  ship_state       text,
  ship_pincode     text,
  notes            text,
  pickup_otp       text check (pickup_otp is null or pickup_otp ~ '^[0-9]{4}$'),
  courier_name     text,
  awb              text,
  tracking_url     text,
  cancel_reason    text,
  placed_at        timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index idx_orders_user on public.orders (user_id, placed_at desc);
create index idx_orders_status on public.orders (status, placed_at desc);
create index idx_orders_placed on public.orders (placed_at desc);
create index idx_orders_phone on public.orders (ship_phone);
create index idx_orders_channel on public.orders (channel, placed_at desc);
create trigger trg_orders_updated before update on public.orders
  for each row execute function public.set_updated_at();

create table public.order_items (
  id           uuid primary key default gen_random_uuid(),
  order_id     uuid not null references public.orders(id) on delete cascade,
  book_id      uuid references public.books(id) on delete set null,
  title        text not null,
  slug         text,
  isbn         text,
  cover_url    text,
  unit_price   numeric(10, 2) not null check (unit_price >= 0),
  mrp          numeric(10, 2) not null check (mrp >= 0),
  qty          integer not null check (qty > 0),
  line_total   numeric(10, 2) not null check (line_total >= 0)
);
create index idx_order_items_order on public.order_items (order_id);
create index idx_order_items_book on public.order_items (book_id);

-- Wholesale cost snapshot for profit reports; staff/service role only.
create table public.order_item_costs (
  order_item_id uuid primary key references public.order_items(id) on delete cascade,
  unit_cost     numeric(10, 2)
);

create table public.order_events (
  id          bigint generated always as identity primary key,
  order_id    uuid not null references public.orders(id) on delete cascade,
  status      text not null,
  note        text,
  actor_id    uuid references auth.users(id) on delete set null,
  created_at  timestamptz not null default now()
);
create index idx_order_events_order on public.order_events (order_id, created_at);

create table public.payments (
  id            uuid primary key default gen_random_uuid(),
  order_id      uuid not null references public.orders(id) on delete cascade,
  method        text not null,
  amount        numeric(10, 2) not null check (amount >= 0),
  status        text not null default 'pending' check (status in ('pending', 'verifying', 'success', 'failed', 'refunded')),
  utr           text unique check (utr is null or utr ~ '^[0-9A-Za-z]{10,22}$'),
  gateway_ref   text,
  payload       jsonb,
  verified_by   uuid references auth.users(id) on delete set null,
  verified_at   timestamptz,
  created_at    timestamptz not null default now()
);
create index idx_payments_order on public.payments (order_id);
create index idx_payments_status on public.payments (status) where status = 'verifying';

alter table public.orders           enable row level security;
alter table public.order_items      enable row level security;
alter table public.order_item_costs enable row level security;   -- service role only
alter table public.order_events     enable row level security;
alter table public.payments         enable row level security;

create policy orders_own on public.orders for select to authenticated using (user_id = auth.uid());
create policy order_items_own on public.order_items for select to authenticated
  using (exists (select 1 from public.orders o where o.id = order_id and o.user_id = auth.uid()));
create policy order_events_own on public.order_events for select to authenticated
  using (exists (select 1 from public.orders o where o.id = order_id and o.user_id = auth.uid()));
create policy payments_own on public.payments for select to authenticated
  using (exists (select 1 from public.orders o where o.id = order_id and o.user_id = auth.uid()));

-- ------------------------------------------------------------ place_order ---
create or replace function public.place_order(
  p_address_id     uuid,
  p_payment_method text,
  p_fulfillment    text default 'delivery',
  p_coupon         text default null,
  p_notes          text default null,
  p_items          jsonb default null      -- Buy Now: [{"book_id": "...", "qty": 1}]; null = use the cart
) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_uid        uuid := auth.uid();
  v_pay        jsonb;
  v_chk        jsonb;
  v_max_qty    integer;
  v_addr       public.addresses;
  v_profile    public.profiles;
  v_email      text;
  v_quote      record;
  v_cpn        record;
  v_item       record;
  v_subtotal   numeric(10, 2) := 0;
  v_discount   numeric(10, 2) := 0;
  v_fee        numeric(10, 2) := 0;
  v_total      numeric(10, 2);
  v_order      uuid := gen_random_uuid();
  v_order_no   text;
  v_otp        text;
  v_item_id    uuid;
  v_from_cart  boolean := p_items is null;
  v_lines      jsonb;
  v_count      integer := 0;
  v_name       text;
  v_phone      text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_payment_method not in ('cod', 'upi') then raise exception 'PAYMENT_METHOD_INVALID'; end if;
  if p_fulfillment not in ('delivery', 'pickup') then raise exception 'FULFILLMENT_INVALID'; end if;

  select value into v_pay from public.site_settings where key = 'payment';
  select value into v_chk from public.site_settings where key = 'checkout';
  if (select (value ->> 'enabled')::boolean from public.site_settings where key = 'maintenance') then
    raise exception 'STORE_MAINTENANCE';
  end if;
  if p_payment_method = 'cod' and not coalesce((v_pay ->> 'cod_enabled')::boolean, true) then raise exception 'COD_DISABLED'; end if;
  if p_payment_method = 'upi' and not coalesce((v_pay ->> 'upi_enabled')::boolean, true) then raise exception 'UPI_DISABLED'; end if;
  if p_fulfillment = 'pickup' and not coalesce((v_chk ->> 'pickup_enabled')::boolean, true) then raise exception 'PICKUP_DISABLED'; end if;
  v_max_qty := coalesce((v_chk ->> 'max_qty_per_item')::int, 10);

  -- 1. Collect requested lines (cart or Buy Now), merged per book.
  if v_from_cart then
    select coalesce(jsonb_agg(jsonb_build_object('book_id', ci.book_id, 'qty', ci.qty)), '[]'::jsonb) into v_lines
      from public.cart_items ci where ci.user_id = v_uid and not ci.saved_for_later;
  else
    select coalesce(jsonb_agg(jsonb_build_object('book_id', x.book_id, 'qty', x.qty)), '[]'::jsonb) into v_lines
      from (select (e ->> 'book_id')::uuid as book_id, sum(coalesce((e ->> 'qty')::int, 1))::int as qty
              from jsonb_array_elements(p_items) e group by 1) x;
  end if;
  v_count := jsonb_array_length(v_lines);
  if v_count = 0 then raise exception 'EMPTY_CART'; end if;
  if exists (select 1 from jsonb_to_recordset(v_lines) as l(book_id uuid, qty int) where l.qty < 1 or l.qty > v_max_qty) then
    raise exception 'QTY_INVALID' using detail = v_max_qty::text;
  end if;

  -- 2. Lock stock rows in a fixed order (no deadlocks) and validate.
  perform 1 from public.inventory i
    where i.book_id in (select l.book_id from jsonb_to_recordset(v_lines) as l(book_id uuid, qty int))
    order by i.book_id for update;
  for v_item in
    select l.book_id, l.qty, b.title, b.status, coalesce(i.on_hand, 0) as on_hand
      from jsonb_to_recordset(v_lines) as l(book_id uuid, qty int)
      left join public.books b on b.id = l.book_id
      left join public.inventory i on i.book_id = l.book_id
  loop
    if v_item.title is null or v_item.status <> 'active' then raise exception 'BOOK_UNAVAILABLE'; end if;
    if v_item.on_hand < v_item.qty then
      raise exception 'OUT_OF_STOCK' using detail = v_item.title;
    end if;
    v_subtotal := v_subtotal + public.book_effective_price(v_item.book_id) * v_item.qty;
  end loop;

  -- 3. Recipient + delivery fee.
  select * into v_profile from public.profiles where id = v_uid;
  select email into v_email from auth.users where id = v_uid;
  if p_address_id is not null then
    select * into v_addr from public.addresses where id = p_address_id and user_id = v_uid;
    if not found then raise exception 'ADDRESS_INVALID'; end if;
  end if;

  if p_fulfillment = 'delivery' then
    if v_addr.id is null then raise exception 'ADDRESS_REQUIRED'; end if;
    select * into v_quote from public.quote_delivery(v_addr.pincode, v_subtotal);
    if not found then raise exception 'NOT_SERVICEABLE'; end if;
    v_fee := v_quote.fee;
    if p_payment_method = 'cod' and not v_quote.cod_available then raise exception 'COD_NOT_AVAILABLE_HERE'; end if;
  end if;
  v_name  := coalesce(v_addr.full_name, v_profile.full_name);
  v_phone := coalesce(v_addr.phone, v_profile.phone);
  if v_name is null or v_phone is null then raise exception 'CONTACT_REQUIRED'; end if;

  -- 4. Coupon.
  if p_coupon is not null and btrim(p_coupon) <> '' then
    select * into v_cpn from public.evaluate_coupon(p_coupon, v_uid, v_subtotal);
    v_discount := v_cpn.discount;
  end if;

  v_total := v_subtotal - v_discount + v_fee;
  if p_payment_method = 'cod' and v_total > coalesce((v_pay ->> 'cod_max_order')::numeric, 1e9) then
    raise exception 'COD_LIMIT_EXCEEDED' using detail = (v_pay ->> 'cod_max_order');
  end if;

  v_order_no := 'MMB-' || to_char(now() at time zone 'Asia/Kolkata', 'YYMM') || '-' || lpad(nextval('public.order_no_seq')::text, 5, '0');
  v_otp := case when p_fulfillment = 'pickup' then lpad((floor(random() * 10000))::int::text, 4, '0') end;

  insert into public.orders (id, order_no, user_id, payment_method, fulfillment, subtotal, discount_total, delivery_fee, total,
                             coupon_code, customer_email, ship_name, ship_phone, ship_line1, ship_line2, ship_landmark,
                             ship_city, ship_district, ship_state, ship_pincode, notes, pickup_otp)
  values (v_order, v_order_no, v_uid, p_payment_method, p_fulfillment, v_subtotal, v_discount, v_fee, v_total,
          case when v_discount > 0 then upper(btrim(p_coupon)) end, v_email, v_name, v_phone,
          v_addr.line1, v_addr.line2, v_addr.landmark, v_addr.city, v_addr.district, v_addr.state, v_addr.pincode,
          nullif(btrim(coalesce(p_notes, '')), ''), v_otp);

  -- 5. Lines, stock, cost snapshot.
  for v_item in
    select l.book_id, l.qty, b.title, b.slug, b.isbn, b.cover_url, b.mrp,
           public.book_effective_price(l.book_id) as price, bp.cost_price
      from jsonb_to_recordset(v_lines) as l(book_id uuid, qty int)
      join public.books b on b.id = l.book_id
      left join public.book_private bp on bp.book_id = l.book_id
  loop
    v_item_id := gen_random_uuid();
    insert into public.order_items (id, order_id, book_id, title, slug, isbn, cover_url, unit_price, mrp, qty, line_total)
    values (v_item_id, v_order, v_item.book_id, v_item.title, v_item.slug, v_item.isbn, v_item.cover_url,
            v_item.price, v_item.mrp, v_item.qty, v_item.price * v_item.qty);
    insert into public.order_item_costs (order_item_id, unit_cost) values (v_item_id, v_item.cost_price);
    update public.inventory set on_hand = on_hand - v_item.qty where book_id = v_item.book_id;
    update public.books set sold_count = sold_count + v_item.qty where id = v_item.book_id;
    insert into public.stock_movements (book_id, delta, reason, order_id, actor_id)
    values (v_item.book_id, -v_item.qty, 'order', v_order, v_uid);
  end loop;

  insert into public.payments (order_id, method, amount) values (v_order, p_payment_method, v_total);
  insert into public.order_events (order_id, status, note, actor_id)
  values (v_order, 'pending', 'Order placed', v_uid);

  if v_discount > 0 then
    insert into public.coupon_redemptions (coupon_id, user_id, order_id, amount) values (v_cpn.coupon_id, v_uid, v_order, v_discount);
    update public.coupons set used_count = used_count + 1 where id = v_cpn.coupon_id;
  end if;

  if v_from_cart then
    delete from public.cart_items where user_id = v_uid and not saved_for_later;
  end if;

  return jsonb_build_object('order_id', v_order, 'order_no', v_order_no, 'total', v_total,
                            'payment_method', p_payment_method);
end $$;
revoke execute on function public.place_order(uuid, text, text, text, text, jsonb) from public, anon;
grant execute on function public.place_order(uuid, text, text, text, text, jsonb) to authenticated;

-- --------------------------------------------- order lifecycle (internal) ---
-- Restocks and reverses the coupon. Shared by customer cancel and staff status changes.
create or replace function public._release_order(p_order uuid, p_actor uuid, p_reason text, p_restock boolean)
returns void
language plpgsql security definer set search_path = public as $$
declare
  it record;
begin
  if p_restock then
    for it in select book_id, qty from public.order_items where order_id = p_order and book_id is not null order by book_id loop
      update public.inventory set on_hand = on_hand + it.qty where book_id = it.book_id;
      update public.books set sold_count = greatest(sold_count - it.qty, 0) where id = it.book_id;
      insert into public.stock_movements (book_id, delta, reason, order_id, actor_id, note)
      values (it.book_id, it.qty, case p_reason when 'return' then 'return' else 'cancel' end, p_order, p_actor, p_reason);
    end loop;
  end if;
  with del as (delete from public.coupon_redemptions where order_id = p_order returning coupon_id)
  update public.coupons c set used_count = greatest(used_count - 1, 0)
    where c.id in (select coupon_id from del);
end $$;
revoke execute on function public._release_order(uuid, uuid, text, boolean) from public, anon, authenticated;

-- Customer: cancel own order while it has not been packed.
create or replace function public.cancel_my_order(p_order uuid, p_reason text default null)
returns void
language plpgsql security definer set search_path = public as $$
declare
  o public.orders;
begin
  select * into o from public.orders where id = p_order and user_id = auth.uid() for update;
  if not found then raise exception 'ORDER_NOT_FOUND'; end if;
  if o.status not in ('pending', 'confirmed') then raise exception 'ORDER_NOT_CANCELLABLE'; end if;
  perform public._release_order(o.id, auth.uid(), 'cancel', true);
  update public.orders
     set status = 'cancelled', cancel_reason = nullif(btrim(coalesce(p_reason, '')), ''),
         payment_status = case when payment_status = 'paid' then 'refunded' else payment_status end
   where id = o.id;
  update public.payments set status = case when status = 'success' then 'refunded' else 'failed' end
   where order_id = o.id and status in ('pending', 'verifying', 'success');
  insert into public.order_events (order_id, status, note, actor_id) values (o.id, 'cancelled', coalesce(p_reason, 'Cancelled by customer'), auth.uid());
end $$;
revoke execute on function public.cancel_my_order(uuid, text) from public, anon;
grant execute on function public.cancel_my_order(uuid, text) to authenticated;

-- Customer: submit the UPI transaction reference (UTR) for manual verification.
create or replace function public.submit_utr(p_order uuid, p_utr text)
returns void
language plpgsql security definer set search_path = public as $$
declare
  o public.orders;
begin
  select * into o from public.orders where id = p_order and user_id = auth.uid() for update;
  if not found then raise exception 'ORDER_NOT_FOUND'; end if;
  if o.payment_method <> 'upi' or o.status in ('cancelled', 'returned') then raise exception 'PAYMENT_NOT_APPLICABLE'; end if;
  if o.payment_status not in ('unpaid', 'failed') then raise exception 'PAYMENT_ALREADY_SUBMITTED'; end if;
  if p_utr !~ '^[0-9A-Za-z]{10,22}$' then raise exception 'UTR_INVALID'; end if;
  if exists (select 1 from public.payments where utr = p_utr and order_id <> o.id) then raise exception 'UTR_ALREADY_USED'; end if;

  update public.payments set utr = p_utr, status = 'verifying'
   where id = (select id from public.payments where order_id = o.id order by created_at desc limit 1);
  update public.orders set payment_status = 'pending_verification' where id = o.id;
  insert into public.order_events (order_id, status, note, actor_id) values (o.id, o.status, 'UTR submitted: ' || p_utr, auth.uid());
end $$;
revoke execute on function public.submit_utr(uuid, text) from public, anon;
grant execute on function public.submit_utr(uuid, text) to authenticated;

-- Staff (service role only): move an order through the pipeline.
create or replace function public.admin_set_order_status(
  p_order uuid, p_status text, p_note text, p_actor uuid, p_restock boolean default true
) returns void
language plpgsql security definer set search_path = public as $$
declare
  o public.orders;
  allowed text[];
begin
  select * into o from public.orders where id = p_order for update;
  if not found then raise exception 'ORDER_NOT_FOUND'; end if;

  allowed := case o.status
    when 'pending'    then array['confirmed', 'processing', 'cancelled']
    when 'confirmed'  then array['processing', 'cancelled']
    when 'processing' then array['ready', 'dispatched', 'cancelled']
    when 'ready'      then array['dispatched', 'delivered', 'cancelled']
    when 'dispatched' then array['delivered', 'returned']
    when 'delivered'  then array['returned']
    else array[]::text[] end;
  if not (p_status = any (allowed)) then
    raise exception 'STATUS_TRANSITION_INVALID' using detail = o.status || ' -> ' || p_status;
  end if;

  if p_status in ('cancelled', 'returned') then
    perform public._release_order(o.id, p_actor, case when p_status = 'returned' then 'return' else 'cancel' end, p_restock);
    update public.orders
       set payment_status = case when payment_status = 'paid' then 'refunded' else payment_status end,
           cancel_reason = coalesce(nullif(btrim(coalesce(p_note, '')), ''), cancel_reason)
     where id = o.id;
    update public.payments set status = case when status = 'success' then 'refunded' else 'failed' end
     where order_id = o.id and status in ('pending', 'verifying', 'success');
  end if;

  if p_status = 'delivered' and o.payment_method = 'cod' and o.payment_status <> 'paid' then
    update public.orders set payment_status = 'paid' where id = o.id;
    update public.payments set status = 'success', verified_by = p_actor, verified_at = now()
     where order_id = o.id and status in ('pending', 'verifying');
  end if;

  update public.orders set status = p_status where id = o.id;
  insert into public.order_events (order_id, status, note, actor_id) values (o.id, p_status, p_note, p_actor);
end $$;
revoke execute on function public.admin_set_order_status(uuid, text, text, uuid, boolean) from public, anon, authenticated;

-- Staff (service role only): approve or reject a UPI payment.
create or replace function public.admin_review_payment(p_order uuid, p_approve boolean, p_note text, p_actor uuid)
returns void
language plpgsql security definer set search_path = public as $$
declare
  o public.orders;
begin
  select * into o from public.orders where id = p_order for update;
  if not found then raise exception 'ORDER_NOT_FOUND'; end if;
  if o.payment_status <> 'pending_verification' then raise exception 'NOTHING_TO_VERIFY'; end if;

  if p_approve then
    update public.payments set status = 'success', verified_by = p_actor, verified_at = now()
     where order_id = o.id and status = 'verifying';
    update public.orders set payment_status = 'paid', status = case when status = 'pending' then 'confirmed' else status end
     where id = o.id;
    insert into public.order_events (order_id, status, note, actor_id)
    values (o.id, case when o.status = 'pending' then 'confirmed' else o.status end, coalesce(p_note, 'Payment verified'), p_actor);
  else
    update public.payments set status = 'failed', verified_by = p_actor, verified_at = now()
     where order_id = o.id and status = 'verifying';
    update public.orders set payment_status = 'failed' where id = o.id;
    insert into public.order_events (order_id, status, note, actor_id)
    values (o.id, o.status, coalesce(p_note, 'Payment could not be verified'), p_actor);
  end if;
end $$;
revoke execute on function public.admin_review_payment(uuid, boolean, text, uuid) from public, anon, authenticated;

-- Public order tracking by order number + phone (no login needed).
create or replace function public.track_order(p_order_no text, p_phone text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  o public.orders;
  digits text := regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g');
begin
  if length(digits) < 8 then return null; end if;
  select * into o from public.orders
   where order_no = upper(btrim(p_order_no))
     and right(regexp_replace(ship_phone, '[^0-9]', '', 'g'), 10) = right(digits, 10);
  if not found then return null; end if;
  return jsonb_build_object(
    'order_no', o.order_no, 'status', o.status, 'payment_status', o.payment_status,
    'fulfillment', o.fulfillment, 'total', o.total, 'placed_at', o.placed_at,
    'courier_name', o.courier_name, 'awb', o.awb, 'tracking_url', o.tracking_url,
    'events', coalesce((select jsonb_agg(jsonb_build_object('status', e.status, 'note', e.note, 'at', e.created_at) order by e.created_at)
                          from public.order_events e where e.order_id = o.id and e.note is distinct from null and e.note not like 'UTR submitted%'), '[]'::jsonb),
    'items', coalesce((select jsonb_agg(jsonb_build_object('title', i.title, 'qty', i.qty)) from public.order_items i where i.order_id = o.id), '[]'::jsonb));
end $$;
grant execute on function public.track_order(text, text) to anon, authenticated;


-- ===== 0004_engagement.sql =====
-- 0004 Engagement: reviews, Q&A, banners, notifications, outbound message queue

-- --------------------------------------------------------------- reviews ---
create table public.reviews (
  id                 uuid primary key default gen_random_uuid(),
  book_id            uuid not null references public.books(id) on delete cascade,
  user_id            uuid not null references auth.users(id) on delete cascade,
  reviewer_name      text,
  rating             smallint not null check (rating between 1 and 5),
  title              text check (title is null or length(title) <= 120),
  body               text check (body is null or length(body) <= 4000),
  verified_purchase  boolean not null default false,
  status             text not null default 'pending' check (status in ('pending', 'published', 'rejected')),
  helpful_count      integer not null default 0 check (helpful_count >= 0),
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  unique (book_id, user_id)
);
create index idx_reviews_book on public.reviews (book_id, status, created_at desc);
create trigger trg_reviews_updated before update on public.reviews
  for each row execute function public.set_updated_at();

create table public.review_votes (
  review_id  uuid not null references public.reviews(id) on delete cascade,
  user_id    uuid not null references auth.users(id) on delete cascade,
  primary key (review_id, user_id)
);

-- Customers can never choose their own status or "verified" flag; staff (service role) can.
create or replace function public.reviews_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is not null then
    new.status := 'pending';
    new.helpful_count := case when tg_op = 'UPDATE' then old.helpful_count else 0 end;
    new.verified_purchase := exists (
      select 1 from public.order_items oi join public.orders o on o.id = oi.order_id
       where o.user_id = new.user_id and oi.book_id = new.book_id and o.status = 'delivered');
    if new.reviewer_name is null then
      select coalesce(nullif(split_part(full_name, ' ', 1), ''), 'Reader') into new.reviewer_name
        from public.profiles where id = new.user_id;
    end if;
  end if;
  return new;
end $$;
revoke execute on function public.reviews_guard() from public, anon, authenticated;
create trigger trg_reviews_guard before insert or update on public.reviews
  for each row execute function public.reviews_guard();

create or replace function public.reviews_rollup() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  b uuid := coalesce(new.book_id, old.book_id);
begin
  update public.books set
    rating_count = (select count(*) from public.reviews where book_id = b and status = 'published'),
    rating_avg   = coalesce((select round(avg(rating)::numeric, 2) from public.reviews where book_id = b and status = 'published'), 0)
   where id = b;
  return null;
end $$;
revoke execute on function public.reviews_rollup() from public, anon, authenticated;
create trigger trg_reviews_rollup after insert or update or delete on public.reviews
  for each row execute function public.reviews_rollup();

create or replace function public.review_votes_rollup() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  r uuid := coalesce(new.review_id, old.review_id);
begin
  update public.reviews set helpful_count = (select count(*) from public.review_votes where review_id = r) where id = r;
  return null;
end $$;
revoke execute on function public.review_votes_rollup() from public, anon, authenticated;
create trigger trg_review_votes_rollup after insert or delete on public.review_votes
  for each row execute function public.review_votes_rollup();

alter table public.reviews      enable row level security;
alter table public.review_votes enable row level security;
create policy reviews_read on public.reviews for select to anon, authenticated
  using (status = 'published' or user_id = auth.uid());
create policy reviews_insert_own on public.reviews for insert to authenticated with check (user_id = auth.uid());
create policy reviews_update_own on public.reviews for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy reviews_delete_own on public.reviews for delete to authenticated using (user_id = auth.uid());
create policy review_votes_own on public.review_votes for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

-- ------------------------------------------------------------------- Q&A ---
create table public.book_questions (
  id           uuid primary key default gen_random_uuid(),
  book_id      uuid not null references public.books(id) on delete cascade,
  user_id      uuid not null references auth.users(id) on delete cascade,
  asker_name   text,
  question     text not null check (length(btrim(question)) between 5 and 1000),
  answer       text,
  answered_at  timestamptz,
  status       text not null default 'pending' check (status in ('pending', 'published', 'rejected')),
  created_at   timestamptz not null default now()
);
create index idx_questions_book on public.book_questions (book_id, status, created_at desc);

create or replace function public.questions_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is not null then
    new.status := 'pending';
    new.answer := case when tg_op = 'UPDATE' then old.answer else null end;
    new.answered_at := case when tg_op = 'UPDATE' then old.answered_at else null end;
    if new.asker_name is null then
      select coalesce(nullif(split_part(full_name, ' ', 1), ''), 'Reader') into new.asker_name
        from public.profiles where id = new.user_id;
    end if;
  end if;
  return new;
end $$;
revoke execute on function public.questions_guard() from public, anon, authenticated;
create trigger trg_questions_guard before insert or update on public.book_questions
  for each row execute function public.questions_guard();

alter table public.book_questions enable row level security;
create policy questions_read on public.book_questions for select to anon, authenticated
  using (status = 'published' or user_id = auth.uid());
create policy questions_insert_own on public.book_questions for insert to authenticated with check (user_id = auth.uid());

-- --------------------------------------------------------------- banners ---
create table public.banners (
  id                uuid primary key default gen_random_uuid(),
  placement         text not null default 'hero' check (placement in ('hero', 'strip')),
  title             text not null,
  title_bn          text,
  subtitle          text,
  subtitle_bn       text,
  image_url         text,
  mobile_image_url  text,
  link_url          text,
  cta_label         text,
  cta_label_bn      text,
  bg_color          text check (bg_color is null or bg_color ~ '^#[0-9a-fA-F]{6}$'),
  sort_order        integer not null default 0,
  starts_at         timestamptz,
  ends_at           timestamptz,
  is_active         boolean not null default true,
  created_at        timestamptz not null default now(),
  check (ends_at is null or starts_at is null or ends_at > starts_at)
);
create index idx_banners_active on public.banners (placement, sort_order) where is_active;
alter table public.banners enable row level security;
create policy banners_read on public.banners for select to anon, authenticated
  using (is_active and (starts_at is null or now() >= starts_at) and (ends_at is null or now() < ends_at));

-- --------------------------------------------------------- notifications ---
create table public.notifications (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users(id) on delete cascade,
  kind        text not null,
  title       text not null,
  body        text,
  link        text,
  read_at     timestamptz,
  created_at  timestamptz not null default now()
);
create index idx_notifications_user on public.notifications (user_id, created_at desc);
alter table public.notifications enable row level security;
create policy notifications_select_own on public.notifications for select to authenticated using (user_id = auth.uid());
create policy notifications_update_own on public.notifications for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

-- Outbound messages (email now; SMS / WhatsApp once a provider key exists).
create table public.outbox (
  id          uuid primary key default gen_random_uuid(),
  channel     text not null check (channel in ('email', 'sms', 'whatsapp')),
  recipient   text not null,
  template    text not null,
  payload     jsonb not null default '{}'::jsonb,
  status      text not null default 'queued' check (status in ('queued', 'sent', 'failed', 'skipped')),
  attempts    integer not null default 0,
  last_error  text,
  created_at  timestamptz not null default now(),
  sent_at     timestamptz
);
create index idx_outbox_queue on public.outbox (created_at) where status = 'queued';
alter table public.outbox enable row level security;   -- service role only

-- ------------------------------------------------------------- enquiries ---
-- Bulk / institutional order requests from the public form (written by the server only).
create table public.enquiries (
  id          uuid primary key default gen_random_uuid(),
  kind        text not null default 'bulk' check (kind in ('bulk', 'support')),
  org         text,
  contact     text not null,
  phone       text not null,
  email       text,
  message     text not null,
  status      text not null default 'new' check (status in ('new', 'contacted', 'closed')),
  handled_by  uuid references auth.users(id) on delete set null,
  created_at  timestamptz not null default now()
);
create index idx_enquiries_status on public.enquiries (status, created_at desc);
alter table public.enquiries enable row level security;   -- service role only


-- ===== 0005_search.sql =====
-- 0005 Search: typo-tolerant, bilingual catalog search with filters and sorting.
-- Runs as the caller (security invoker) so RLS keeps drafts/archived books out.

create or replace function public.escape_like(p_text text) returns text
language sql immutable as $$
  select replace(replace(replace(p_text, '\', '\\'), '%', '\%'), '_', '\_');
$$;

create or replace function public.search_books(
  p_q          text    default null,
  p_category   uuid    default null,
  p_min        numeric default null,
  p_max        numeric default null,
  p_lang       text    default null,
  p_in_stock   boolean default false,
  p_sort       text    default 'relevance',
  p_limit      integer default 24,
  p_offset     integer default 0
) returns table (
  id uuid, slug text, title text, title_bn text, cover_url text,
  mrp numeric, price numeric, discount_pct integer, rating_avg numeric, rating_count integer,
  in_stock boolean, low_stock boolean, on_hand integer, author_names text, author_names_bn text,
  publisher_name text, language text, deal_ends_at timestamptz, total_count bigint
)
language sql stable security invoker set search_path = public, extensions as $$
  with recursive
  cats as (
    select c.id from public.categories c where c.id = p_category
    union
    select c.id from public.categories c join cats on c.parent_id = cats.id
  ),
  q as (
    select nullif(lower(btrim(coalesce(p_q, ''))), '') as t
  ),
  hits as (
    select v.*, b.search_text,
           case
             when q.t is null then 0::real
             else greatest(
               word_similarity(q.t, b.search_text),
               similarity(b.search_text, q.t),
               case when not exists (
                      select 1 from unnest(string_to_array(q.t, ' ')) tok
                       where tok <> '' and b.search_text not like '%' || public.escape_like(tok) || '%')
                    then 0.95::real else 0::real end)
           end as score
      from public.v_books v
      join public.books b on b.id = v.id
      cross join q
     where (q.t is null
            or not exists (
                 select 1 from unnest(string_to_array(q.t, ' ')) tok
                  where tok <> '' and b.search_text not like '%' || public.escape_like(tok) || '%')
            or word_similarity(q.t, b.search_text) >= 0.4)
       and (p_category is null
            or exists (select 1 from public.book_categories bc
                        where bc.book_id = v.id and bc.category_id in (select cats.id from cats)))
       and (p_min is null or v.price >= p_min)
       and (p_max is null or v.price <= p_max)
       and (p_lang is null or v.language = p_lang)
       and (not p_in_stock or v.in_stock)
  )
  select h.id, h.slug, h.title, h.title_bn, h.cover_url, h.mrp, h.price, h.discount_pct, h.rating_avg, h.rating_count,
         h.in_stock, h.low_stock, h.on_hand, h.author_names, h.author_names_bn, h.publisher_name, h.language,
         h.deal_ends_at, count(*) over () as total_count
    from hits h
   order by
     case p_sort when 'price_asc'  then h.price end asc,
     case p_sort when 'price_desc' then h.price end desc,
     case p_sort when 'newest'     then h.created_at end desc,
     case p_sort when 'popular'    then h.sold_count end desc,
     case p_sort when 'rating'     then h.rating_avg end desc,
     case p_sort when 'discount'   then h.discount_pct end desc,
     h.score desc,
     h.in_stock desc,
     h.sold_count desc,
     h.title asc
   limit greatest(least(p_limit, 100), 1)
  offset greatest(p_offset, 0);
$$;


-- ===== 0006_admin.sql =====
-- 0006 Admin: counters, dashboard, reports, stock adjustment, counter (POS) sales.
-- Everything here is SECURITY DEFINER and executable by the service role only;
-- the Next.js server calls it after checking the staff member's role.

create sequence public.pos_no_seq start 1001;

-- ---------------------------------------------------------------- counters ---
create or replace function public.admin_counters() returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'pending_orders',  (select count(*) from public.orders where status = 'pending' and channel = 'online'),
    'verify_payments', (select count(*) from public.orders where payment_status = 'pending_verification' and status not in ('cancelled', 'returned')),
    'low_stock',       (select count(*) from public.inventory i join public.books b on b.id = i.book_id
                         where b.status = 'active' and i.on_hand <= i.low_stock_threshold),
    'enquiries',       (select count(*) from public.enquiries where status = 'new'),
    'reviews',         (select count(*) from public.reviews where status = 'pending')
                     + (select count(*) from public.book_questions where status = 'pending'));
$$;

-- --------------------------------------------------------------- dashboard ---
create or replace function public.admin_dashboard(p_days integer default 30) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  tz constant text := 'Asia/Kolkata';
  today date := (now() at time zone tz)::date;
  days integer := greatest(least(p_days, 366), 1);
  res jsonb;
begin
  with o as (
    select o.*, (o.placed_at at time zone tz)::date as d
      from public.orders o
     where o.status not in ('cancelled', 'returned')
       and o.placed_at >= (today - days)::timestamp at time zone tz
  ),
  day_series as (
    select gs::date as d,
           coalesce(sum(o.total), 0) as sales,
           count(o.id) as orders
      from generate_series(today - (days - 1), today, interval '1 day') gs
      left join o on o.d = gs::date
     group by gs
  ),
  top as (
    select oi.title, sum(oi.qty)::int as qty, sum(oi.line_total) as revenue
      from public.order_items oi join o on o.id = oi.order_id
     group by oi.title order by sum(oi.qty) desc, sum(oi.line_total) desc limit 10
  ),
  profit as (
    -- Only lines whose wholesale cost is known count towards profit (unknown cost would look like 100% margin).
    select coalesce(sum(oi.line_total - c.unit_cost * oi.qty), 0) as p,
           count(*) as known
      from public.order_items oi
      join o on o.id = oi.order_id
      join public.order_item_costs c on c.order_item_id = oi.id and c.unit_cost is not null
  )
  select jsonb_build_object(
    'today',     jsonb_build_object('sales', coalesce((select sum(total) from o where d = today), 0),
                                    'orders', (select count(*) from o where d = today)),
    'yesterday', jsonb_build_object('sales', coalesce((select sum(total) from o where d = today - 1), 0),
                                    'orders', (select count(*) from o where d = today - 1)),
    'period',    jsonb_build_object('sales', coalesce((select sum(total) from o), 0),
                                    'orders', (select count(*) from o),
                                    'aov', coalesce((select round(avg(total), 2) from o), 0),
                                    'profit', (select p from profit)),
    'to_dispatch', (select count(*) from public.orders where status in ('confirmed', 'processing', 'ready') and channel = 'online'),
    'series',    coalesce((select jsonb_agg(jsonb_build_object('d', d, 'sales', sales, 'orders', orders) order by d) from day_series), '[]'::jsonb),
    'top_books', coalesce((select jsonb_agg(jsonb_build_object('title', title, 'qty', qty, 'revenue', revenue)) from top), '[]'::jsonb)
  ) into res;
  return res;
end $$;

-- ------------------------------------------------------------------ stock ---
create or replace function public.admin_low_stock(p_limit integer default 50)
returns table (book_id uuid, title text, slug text, on_hand integer, threshold integer, rack_location text)
language sql stable security definer set search_path = public as $$
  select b.id, b.title, b.slug, i.on_hand, i.low_stock_threshold, bp.rack_location
    from public.inventory i
    join public.books b on b.id = i.book_id
    left join public.book_private bp on bp.book_id = b.id
   where b.status = 'active' and i.on_hand <= i.low_stock_threshold
   order by i.on_hand asc, b.title
   limit greatest(p_limit, 1);
$$;

create or replace function public.admin_adjust_stock(p_book uuid, p_delta integer, p_reason text, p_note text, p_actor uuid)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  cur integer;
begin
  if p_delta = 0 then raise exception 'DELTA_ZERO'; end if;
  if p_reason not in ('restock', 'adjust', 'import', 'return') then raise exception 'REASON_INVALID'; end if;
  select on_hand into cur from public.inventory where book_id = p_book for update;
  if not found then raise exception 'BOOK_NOT_FOUND'; end if;
  if cur + p_delta < 0 then raise exception 'STOCK_NEGATIVE' using detail = cur::text; end if;
  update public.inventory set on_hand = cur + p_delta where book_id = p_book;
  insert into public.stock_movements (book_id, delta, reason, note, actor_id) values (p_book, p_delta, p_reason, p_note, p_actor);
  -- Back in stock: flag customers who asked to be notified.
  if cur = 0 and cur + p_delta > 0 then
    update public.stock_alerts set notified_at = null where book_id = p_book;
  end if;
  return cur + p_delta;
end $$;

create or replace function public.admin_set_stock(p_book uuid, p_on_hand integer, p_note text, p_actor uuid)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  cur integer;
begin
  if p_on_hand < 0 then raise exception 'STOCK_NEGATIVE'; end if;
  select on_hand into cur from public.inventory where book_id = p_book for update;
  if not found then raise exception 'BOOK_NOT_FOUND'; end if;
  if p_on_hand = cur then return cur; end if;
  update public.inventory set on_hand = p_on_hand where book_id = p_book;
  insert into public.stock_movements (book_id, delta, reason, note, actor_id) values (p_book, p_on_hand - cur, 'adjust', p_note, p_actor);
  return p_on_hand;
end $$;

-- ------------------------------------------------------- counter (POS) sale ---
-- p_items: [{"book_id": "...", "qty": 1, "unit_price": 350}]  (unit_price optional, capped at MRP)
create or replace function public.admin_pos_sale(p_items jsonb, p_actor uuid, p_payment text default 'cash', p_customer text default null, p_phone text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_order uuid := gen_random_uuid();
  v_no text;
  v_item record;
  v_line_id uuid;
  v_total numeric(10, 2) := 0;
  v_price numeric(10, 2);
begin
  if p_payment not in ('cash', 'upi') then raise exception 'PAYMENT_METHOD_INVALID'; end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then raise exception 'EMPTY_CART'; end if;

  perform 1 from public.inventory i
    where i.book_id in (select (e ->> 'book_id')::uuid from jsonb_array_elements(p_items) e)
    order by i.book_id for update;

  for v_item in
    select (e ->> 'book_id')::uuid as book_id, sum((e ->> 'qty')::int)::int as qty,
           max(nullif(e ->> 'unit_price', '')::numeric) as unit_price
      from jsonb_array_elements(p_items) e group by 1
  loop
    if v_item.qty < 1 then raise exception 'QTY_INVALID'; end if;
    if (select coalesce(on_hand, 0) from public.inventory where book_id = v_item.book_id) < v_item.qty then
      raise exception 'OUT_OF_STOCK' using detail = (select title from public.books where id = v_item.book_id);
    end if;
    v_price := coalesce(v_item.unit_price, public.book_effective_price(v_item.book_id));
    if v_price < 0 or v_price > (select mrp from public.books where id = v_item.book_id) then raise exception 'PRICE_INVALID'; end if;
    v_total := v_total + v_price * v_item.qty;
  end loop;

  v_no := 'POS-' || to_char(now() at time zone 'Asia/Kolkata', 'YYMM') || '-' || lpad(nextval('public.pos_no_seq')::text, 5, '0');
  insert into public.orders (id, order_no, user_id, channel, status, payment_method, payment_status, fulfillment, subtotal, total,
                             ship_name, ship_phone, placed_at)
  values (v_order, v_no, null, 'pos', 'delivered', p_payment, 'paid', 'pickup', v_total, v_total,
          coalesce(nullif(btrim(p_customer), ''), 'Walk-in customer'), coalesce(nullif(btrim(p_phone), ''), '0000000000'), now());

  for v_item in
    select l.book_id, l.qty, coalesce(l.unit_price, public.book_effective_price(l.book_id)) as price,
           b.title, b.slug, b.isbn, b.cover_url, b.mrp, bp.cost_price
      from (select (e ->> 'book_id')::uuid as book_id, sum((e ->> 'qty')::int)::int as qty,
                   max(nullif(e ->> 'unit_price', '')::numeric) as unit_price
              from jsonb_array_elements(p_items) e group by 1) l
      join public.books b on b.id = l.book_id
      left join public.book_private bp on bp.book_id = l.book_id
  loop
    v_line_id := gen_random_uuid();
    insert into public.order_items (id, order_id, book_id, title, slug, isbn, cover_url, unit_price, mrp, qty, line_total)
    values (v_line_id, v_order, v_item.book_id, v_item.title, v_item.slug, v_item.isbn, v_item.cover_url,
            v_item.price, v_item.mrp, v_item.qty, v_item.price * v_item.qty);
    insert into public.order_item_costs (order_item_id, unit_cost) values (v_line_id, v_item.cost_price);
    update public.inventory set on_hand = on_hand - v_item.qty where book_id = v_item.book_id;
    update public.books set sold_count = sold_count + v_item.qty where id = v_item.book_id;
    insert into public.stock_movements (book_id, delta, reason, order_id, actor_id, note)
    values (v_item.book_id, -v_item.qty, 'pos_sale', v_order, p_actor, 'Counter sale');
  end loop;

  insert into public.payments (order_id, method, amount, status, verified_by, verified_at)
  values (v_order, p_payment, v_total, 'success', p_actor, now());
  insert into public.order_events (order_id, status, note, actor_id) values (v_order, 'delivered', 'Counter sale', p_actor);

  return jsonb_build_object('order_id', v_order, 'order_no', v_no, 'total', v_total);
end $$;

-- ----------------------------------------------------------------- reports ---
-- Sales summary between two IST dates (inclusive). Cancelled/returned orders are excluded.
create or replace function public.admin_sales_report(p_from date, p_to date) returns jsonb
language sql stable security definer set search_path = public as $$
  with o as (
    select o.*, (o.placed_at at time zone 'Asia/Kolkata')::date as d,
           extract(hour from (o.placed_at at time zone 'Asia/Kolkata'))::int as h
      from public.orders o
     where o.status not in ('cancelled', 'returned')
       and (o.placed_at at time zone 'Asia/Kolkata')::date between p_from and p_to
  )
  select jsonb_build_object(
    'totals', (select jsonb_build_object('orders', count(*), 'gross', coalesce(sum(subtotal), 0), 'discount', coalesce(sum(discount_total), 0),
                                         'delivery', coalesce(sum(delivery_fee), 0), 'net', coalesce(sum(total), 0),
                                         'units', coalesce((select sum(oi.qty) from public.order_items oi where oi.order_id in (select id from o)), 0),
                                         'profit', coalesce((select sum(oi.line_total - c.unit_cost * oi.qty) from public.order_items oi join public.order_item_costs c on c.order_item_id = oi.id and c.unit_cost is not null
                                                              where oi.order_id in (select id from o)), 0))
                 from o),
    'by_day', coalesce((select jsonb_agg(x order by x.d) from (select d, count(*) as orders, sum(total) as net from o group by d) x), '[]'::jsonb),
    'by_hour', coalesce((select jsonb_agg(x order by x.h) from (select h, count(*) as orders, sum(total) as net from o group by h) x), '[]'::jsonb),
    'by_payment', coalesce((select jsonb_agg(x) from (select payment_method, count(*) as orders, sum(total) as net from o group by payment_method) x), '[]'::jsonb),
    'by_channel', coalesce((select jsonb_agg(x) from (select channel, count(*) as orders, sum(total) as net from o group by channel) x), '[]'::jsonb),
    'by_district', coalesce((select jsonb_agg(x order by x.orders desc) from (
        select coalesce(nullif(ship_district, ''), nullif(ship_city, ''), 'Unknown') as district, count(*) as orders, sum(total) as net
          from o where channel = 'online' group by 1 order by 2 desc limit 15) x), '[]'::jsonb),
    'top_books', coalesce((select jsonb_agg(x) from (
        select oi.title, sum(oi.qty)::int as qty, sum(oi.line_total) as revenue
          from public.order_items oi where oi.order_id in (select id from o) group by oi.title order by 2 desc, 3 desc limit 20) x), '[]'::jsonb)
  );
$$;

-- Slow movers: in stock, but nothing sold for p_days days.
create or replace function public.admin_dead_stock(p_days integer default 90, p_limit integer default 100)
returns table (book_id uuid, title text, slug text, on_hand integer, cost_value numeric, last_sold date)
language sql stable security definer set search_path = public as $$
  select b.id, b.title, b.slug, i.on_hand,
         coalesce(bp.cost_price, 0) * i.on_hand,
         (select max((o.placed_at at time zone 'Asia/Kolkata')::date)
            from public.order_items oi join public.orders o on o.id = oi.order_id
           where oi.book_id = b.id and o.status not in ('cancelled', 'returned'))
    from public.books b
    join public.inventory i on i.book_id = b.id
    left join public.book_private bp on bp.book_id = b.id
   where b.status = 'active' and i.on_hand > 0
     and not exists (select 1 from public.order_items oi join public.orders o on o.id = oi.order_id
                      where oi.book_id = b.id and o.status not in ('cancelled', 'returned')
                        and o.placed_at >= now() - make_interval(days => p_days))
   order by coalesce(bp.cost_price, 0) * i.on_hand desc, i.on_hand desc
   limit greatest(p_limit, 1);
$$;

-- HSN-wise summary for GSTR-1 (printed books, HSN 4901, nil-rated).
create or replace function public.admin_hsn_summary(p_from date, p_to date)
returns table (hsn_code text, description text, uqc text, total_qty bigint, total_value numeric, taxable_value numeric, gst_rate numeric)
language sql stable security definer set search_path = public as $$
  select coalesce(b.hsn_code, '4901'), 'Printed books, brochures, leaflets', 'NOS',
         sum(oi.qty)::bigint, sum(oi.line_total), (case when max(b.gst_rate) = 0 then 0 else sum(oi.line_total) end), coalesce(max(b.gst_rate), 0)
    from public.order_items oi
    join public.orders o on o.id = oi.order_id
    left join public.books b on b.id = oi.book_id
   where o.status not in ('cancelled', 'returned')
     and (o.placed_at at time zone 'Asia/Kolkata')::date between p_from and p_to
   group by coalesce(b.hsn_code, '4901')
   order by 1;
$$;

-- Revoke the default PUBLIC/anon/authenticated execute on every admin function.
do $$
declare
  f record;
begin
  for f in
    select p.oid::regprocedure as sig
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public' and p.proname like 'admin\_%'
  loop
    execute format('revoke execute on function %s from public, anon, authenticated', f.sig);
  end loop;
end $$;


-- ===== 0007_admin_books_storage.sql =====
-- 0007 Admin book editor (atomic save) and media storage bucket.

-- p: {
--   id?: uuid, slug, title, title_bn?, subtitle?, description?, description_bn?, isbn?,
--   language, binding, condition, edition?, edition_year?, pages?, weight_g?, class_level?,
--   mrp, sale_price, hsn_code?, gst_rate?, cover_url?, gallery: [url], preview_pages: [url],
--   status, is_featured,
--   publisher?: {name, name_bn?, slug}, authors: [{name, name_bn?, slug, role?}], category_ids: [uuid],
--   cost_price?, rack_location?, supplier_note?, on_hand? (new books only), low_stock_threshold?
-- }
create or replace function public.admin_save_book(p jsonb, p_actor uuid) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  v_pub uuid;
  v_author uuid;
  v_slug text;
  a jsonb;
  pos integer := 0;
  is_new boolean := v_id is null;
begin
  if p ->> 'publisher' is not null and p -> 'publisher' <> 'null'::jsonb and nullif(btrim(p -> 'publisher' ->> 'name'), '') is not null then
    select id into v_pub from public.publishers where lower(name) = lower(btrim(p -> 'publisher' ->> 'name'));
    if v_pub is null then
      v_slug := p -> 'publisher' ->> 'slug';
      if exists (select 1 from public.publishers where slug = v_slug) then v_slug := v_slug || '-' || substr(md5(random()::text), 1, 4); end if;
      insert into public.publishers (slug, name, name_bn)
      values (v_slug, btrim(p -> 'publisher' ->> 'name'), nullif(btrim(coalesce(p -> 'publisher' ->> 'name_bn', '')), ''))
      returning id into v_pub;
    end if;
  end if;

  if is_new then
    insert into public.books (slug, title, title_bn, subtitle, description, description_bn, isbn, publisher_id, language, edition,
                              edition_year, pages, binding, condition, weight_g, class_level, mrp, sale_price, hsn_code, gst_rate,
                              cover_url, gallery, preview_pages, status, is_featured)
    values (p ->> 'slug', btrim(p ->> 'title'), nullif(btrim(coalesce(p ->> 'title_bn', '')), ''), nullif(btrim(coalesce(p ->> 'subtitle', '')), ''),
            nullif(btrim(coalesce(p ->> 'description', '')), ''), nullif(btrim(coalesce(p ->> 'description_bn', '')), ''),
            nullif(btrim(coalesce(p ->> 'isbn', '')), ''), v_pub, coalesce(p ->> 'language', 'bn'), nullif(btrim(coalesce(p ->> 'edition', '')), ''),
            nullif(p ->> 'edition_year', '')::int, nullif(p ->> 'pages', '')::int, coalesce(p ->> 'binding', 'paperback'),
            coalesce(p ->> 'condition', 'new'), nullif(p ->> 'weight_g', '')::int, nullif(btrim(coalesce(p ->> 'class_level', '')), ''),
            (p ->> 'mrp')::numeric, (p ->> 'sale_price')::numeric, coalesce(nullif(p ->> 'hsn_code', ''), '4901'),
            coalesce(nullif(p ->> 'gst_rate', '')::numeric, 0), nullif(p ->> 'cover_url', ''),
            coalesce(p -> 'gallery', '[]'::jsonb), coalesce(p -> 'preview_pages', '[]'::jsonb),
            coalesce(p ->> 'status', 'draft')::public.book_status, coalesce((p ->> 'is_featured')::boolean, false))
    returning id into v_id;
  else
    update public.books set
      slug = coalesce(nullif(p ->> 'slug', ''), slug),
      title = btrim(p ->> 'title'), title_bn = nullif(btrim(coalesce(p ->> 'title_bn', '')), ''),
      subtitle = nullif(btrim(coalesce(p ->> 'subtitle', '')), ''),
      description = nullif(btrim(coalesce(p ->> 'description', '')), ''), description_bn = nullif(btrim(coalesce(p ->> 'description_bn', '')), ''),
      isbn = nullif(btrim(coalesce(p ->> 'isbn', '')), ''), publisher_id = v_pub,
      language = coalesce(p ->> 'language', language), edition = nullif(btrim(coalesce(p ->> 'edition', '')), ''),
      edition_year = nullif(p ->> 'edition_year', '')::int, pages = nullif(p ->> 'pages', '')::int,
      binding = coalesce(p ->> 'binding', binding), condition = coalesce(p ->> 'condition', condition),
      weight_g = nullif(p ->> 'weight_g', '')::int, class_level = nullif(btrim(coalesce(p ->> 'class_level', '')), ''),
      mrp = (p ->> 'mrp')::numeric, sale_price = (p ->> 'sale_price')::numeric,
      hsn_code = coalesce(nullif(p ->> 'hsn_code', ''), hsn_code), gst_rate = coalesce(nullif(p ->> 'gst_rate', '')::numeric, gst_rate),
      cover_url = nullif(p ->> 'cover_url', ''), gallery = coalesce(p -> 'gallery', gallery),
      preview_pages = coalesce(p -> 'preview_pages', preview_pages),
      status = coalesce(p ->> 'status', status::text)::public.book_status,
      is_featured = coalesce((p ->> 'is_featured')::boolean, is_featured)
    where id = v_id;
    if not found then raise exception 'BOOK_NOT_FOUND'; end if;
  end if;

  -- Authors: replace the list, creating unknown authors on the fly.
  if p ? 'authors' then
    delete from public.book_authors where book_id = v_id;
    for a in select * from jsonb_array_elements(p -> 'authors') loop
      continue when nullif(btrim(a ->> 'name'), '') is null;
      select id into v_author from public.authors where lower(name) = lower(btrim(a ->> 'name'));
      if v_author is null then
        v_slug := a ->> 'slug';
        if exists (select 1 from public.authors where slug = v_slug) then v_slug := v_slug || '-' || substr(md5(random()::text), 1, 4); end if;
        insert into public.authors (slug, name, name_bn)
        values (v_slug, btrim(a ->> 'name'), nullif(btrim(coalesce(a ->> 'name_bn', '')), ''))
        returning id into v_author;
      end if;
      insert into public.book_authors (book_id, author_id, role, position)
      values (v_id, v_author, coalesce(a ->> 'role', 'author'), pos)
      on conflict do nothing;
      pos := pos + 1;
    end loop;
  end if;

  if p ? 'category_ids' then
    delete from public.book_categories where book_id = v_id;
    insert into public.book_categories (book_id, category_id)
    select v_id, (c)::uuid from jsonb_array_elements_text(p -> 'category_ids') c
    on conflict do nothing;
  end if;

  -- Staff-only fields and stock settings.
  insert into public.book_private (book_id, cost_price, rack_location, supplier_note)
  values (v_id, nullif(p ->> 'cost_price', '')::numeric, nullif(btrim(coalesce(p ->> 'rack_location', '')), ''), nullif(btrim(coalesce(p ->> 'supplier_note', '')), ''))
  on conflict (book_id) do update set
    cost_price = case when p ? 'cost_price' then excluded.cost_price else public.book_private.cost_price end,
    rack_location = excluded.rack_location,
    supplier_note = excluded.supplier_note;

  if is_new and nullif(p ->> 'on_hand', '') is not null and (p ->> 'on_hand')::int > 0 then
    update public.inventory set on_hand = (p ->> 'on_hand')::int where book_id = v_id;
    insert into public.stock_movements (book_id, delta, reason, note, actor_id)
    values (v_id, (p ->> 'on_hand')::int, 'restock', 'Opening stock', p_actor);
  end if;
  if nullif(p ->> 'low_stock_threshold', '') is not null then
    update public.inventory set low_stock_threshold = (p ->> 'low_stock_threshold')::int where book_id = v_id;
  end if;

  perform public.refresh_book_search(v_id);
  return v_id;
end $$;
revoke execute on function public.admin_save_book(jsonb, uuid) from public, anon, authenticated;

-- Bulk price tool: change price for every book of a publisher / category by a percentage of MRP.
-- p_mode 'discount_pct': set sale_price = mrp * (1 - pct/100); 'adjust_pct': sale_price * (1 + pct/100) (capped at MRP).
create or replace function public.admin_bulk_price(p_publisher uuid, p_category uuid, p_mode text, p_pct numeric, p_actor uuid)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  n integer;
begin
  if p_publisher is null and p_category is null then raise exception 'SCOPE_REQUIRED'; end if;
  if p_mode not in ('discount_pct', 'adjust_pct') then raise exception 'MODE_INVALID'; end if;
  if p_mode = 'discount_pct' and (p_pct < 0 or p_pct > 90) then raise exception 'PCT_INVALID'; end if;
  if p_mode = 'adjust_pct' and (p_pct < -90 or p_pct > 100) then raise exception 'PCT_INVALID'; end if;

  update public.books b set sale_price = least(b.mrp, greatest(0, round(
      case p_mode when 'discount_pct' then b.mrp * (1 - p_pct / 100) else b.sale_price * (1 + p_pct / 100) end, 0)))
   where b.status <> 'archived'
     and (p_publisher is null or b.publisher_id = p_publisher)
     and (p_category is null or exists (select 1 from public.book_categories bc where bc.book_id = b.id and bc.category_id = p_category));
  get diagnostics n = row_count;
  return n;
end $$;
revoke execute on function public.admin_bulk_price(uuid, uuid, text, numeric, uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------- storage ---
-- Public bucket for book covers, previews and banners. Uploads go through the
-- server (service role); everyone can read.
do $$
begin
  if exists (select 1 from information_schema.schemata where schema_name = 'storage') then
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('media', 'media', true, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
    on conflict (id) do update set public = true, file_size_limit = 5242880, allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp'];
  end if;
end $$;


-- ===== 0008_partners.sql =====
-- 0008 Partners: publishers, authors and suppliers (Indian or foreign) who apply to supply books.
-- The shop approves an application; an approved partner can then submit books, which the shop
-- reviews and turns into its own (draft) catalogue entries. Partners never sell directly.
-- Safe to run more than once.

create table if not exists public.partners (
  id                 uuid primary key default gen_random_uuid(),
  user_id            uuid not null unique references auth.users(id) on delete cascade,
  kind               text not null check (kind in ('publisher', 'author', 'supplier')),
  name               text not null check (length(btrim(name)) between 2 and 150),
  contact_person     text not null check (length(btrim(contact_person)) between 2 and 100),
  email              text not null check (length(email) between 5 and 200),
  phone              text not null check (length(phone) between 6 and 25),
  country            text not null check (length(btrim(country)) between 2 and 60),
  address            text not null check (length(btrim(address)) between 5 and 500),
  website            text check (website is null or length(website) <= 300),
  tax_id             text check (tax_id is null or length(tax_id) <= 40),
  catalogue          text not null check (length(btrim(catalogue)) between 10 and 2000),
  terms_version      text not null,
  terms_accepted_at  timestamptz not null default now(),
  status             text not null default 'pending' check (status in ('pending', 'approved', 'rejected', 'suspended')),
  admin_note         text check (admin_note is null or length(admin_note) <= 1000),
  reviewed_by        uuid references auth.users(id) on delete set null,
  reviewed_at        timestamptz,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create index if not exists idx_partners_status on public.partners (status, created_at desc);

create table if not exists public.partner_submissions (
  id            uuid primary key default gen_random_uuid(),
  partner_id    uuid not null references public.partners(id) on delete cascade,
  title         text not null check (length(btrim(title)) between 1 and 250),
  title_bn      text check (title_bn is null or length(title_bn) <= 250),
  authors       text not null check (length(btrim(authors)) between 2 and 500),
  publisher     text check (publisher is null or length(publisher) <= 120),
  isbn          text check (isbn is null or isbn ~ '^\d{10}(\d{3})?$'),
  language      text not null default 'bn' check (language in ('bn', 'en', 'hi', 'ur', 'sa', 'other')),
  binding       text not null default 'paperback' check (binding in ('paperback', 'hardcover')),
  edition       text check (edition is null or length(edition) <= 60),
  pages         integer check (pages is null or pages between 1 and 20000),
  mrp           numeric(10, 2) not null check (mrp > 0 and mrp <= 1000000),
  supply_price  numeric(10, 2) not null check (supply_price >= 0 and supply_price <= 1000000),
  currency      text not null default 'INR' check (currency ~ '^[A-Z]{3}$'),
  quantity      integer check (quantity is null or quantity between 0 and 1000000),
  description   text check (description is null or length(description) <= 4000),
  cover_url     text check (cover_url is null or length(cover_url) <= 500),
  status        text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  admin_note    text check (admin_note is null or length(admin_note) <= 1000),
  book_id       uuid references public.books(id) on delete set null,
  reviewed_at   timestamptz,
  created_at    timestamptz not null default now()
);
create index if not exists idx_partner_sub_partner on public.partner_submissions (partner_id, created_at desc);
create index if not exists idx_partner_sub_pending on public.partner_submissions (created_at) where status = 'pending';

alter table public.partners enable row level security;
alter table public.partner_submissions enable row level security;
drop policy if exists partners_select_own on public.partners;
create policy partners_select_own on public.partners for select to authenticated using (user_id = auth.uid());
drop policy if exists partner_sub_select_own on public.partner_submissions;
create policy partner_sub_select_own on public.partner_submissions for select to authenticated
  using (exists (select 1 from public.partners p where p.id = partner_id and p.user_id = auth.uid()));
-- Writes: the functions below (partners) or the service role (admin panel).

-- Apply, or re-apply after a rejection. Approved and suspended partners cannot overwrite their record.
create or replace function public.apply_partner(p jsonb, p_terms_version text) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_existing public.partners;
  v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if coalesce(p_terms_version, '') = '' then raise exception 'TERMS_REQUIRED'; end if;
  if not public.hit_rate_limit('partner-apply:' || v_uid::text, 5, 86400) then raise exception 'RATE_LIMITED'; end if;
  select * into v_existing from public.partners where user_id = v_uid;
  if v_existing.id is not null and v_existing.status in ('approved', 'suspended') then raise exception 'PARTNER_EXISTS'; end if;

  insert into public.partners (user_id, kind, name, contact_person, email, phone, country, address, website, tax_id, catalogue, terms_version, terms_accepted_at, status)
  values (v_uid, p ->> 'kind', btrim(p ->> 'name'), btrim(p ->> 'contact_person'), lower(btrim(p ->> 'email')), btrim(p ->> 'phone'),
          btrim(p ->> 'country'), btrim(p ->> 'address'), nullif(btrim(coalesce(p ->> 'website', '')), ''),
          nullif(btrim(coalesce(p ->> 'tax_id', '')), ''), btrim(p ->> 'catalogue'), p_terms_version, now(), 'pending')
  on conflict (user_id) do update set
    kind = excluded.kind, name = excluded.name, contact_person = excluded.contact_person, email = excluded.email,
    phone = excluded.phone, country = excluded.country, address = excluded.address, website = excluded.website,
    tax_id = excluded.tax_id, catalogue = excluded.catalogue, terms_version = excluded.terms_version,
    terms_accepted_at = now(), status = 'pending', admin_note = null, reviewed_by = null, reviewed_at = null, updated_at = now()
  returning id into v_id;
  return v_id;
end $$;
revoke execute on function public.apply_partner(jsonb, text) from public, anon;
grant execute on function public.apply_partner(jsonb, text) to authenticated;

-- Submit a book for review (approved partners only, max 50 a day).
create or replace function public.submit_partner_book(p jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_partner uuid;
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  select id into v_partner from public.partners where user_id = auth.uid() and status = 'approved';
  if v_partner is null then raise exception 'PARTNER_NOT_APPROVED'; end if;
  if not public.hit_rate_limit('partner-book:' || v_partner::text, 50, 86400) then raise exception 'RATE_LIMITED'; end if;
  insert into public.partner_submissions (partner_id, title, title_bn, authors, publisher, isbn, language, binding, edition, pages,
                                          mrp, supply_price, currency, quantity, description, cover_url)
  values (v_partner, btrim(p ->> 'title'), nullif(btrim(coalesce(p ->> 'title_bn', '')), ''), btrim(p ->> 'authors'),
          nullif(btrim(coalesce(p ->> 'publisher', '')), ''), nullif(p ->> 'isbn', ''), coalesce(p ->> 'language', 'bn'),
          coalesce(p ->> 'binding', 'paperback'), nullif(btrim(coalesce(p ->> 'edition', '')), ''), nullif(p ->> 'pages', '')::int,
          (p ->> 'mrp')::numeric, (p ->> 'supply_price')::numeric, coalesce(p ->> 'currency', 'INR'), nullif(p ->> 'quantity', '')::int,
          nullif(btrim(coalesce(p ->> 'description', '')), ''), nullif(p ->> 'cover_url', ''))
  returning id into v_id;
  return v_id;
end $$;
revoke execute on function public.submit_partner_book(jsonb) from public, anon;
grant execute on function public.submit_partner_book(jsonb) to authenticated;

